import { JSON } from "../..";
import { bs } from "../../../lib/as-bs";
import { expect } from "../../__tests__/lib";
import { bench, blackbox, dumpToFile } from "../lib/bench";
import {
  GrowingObject,
  OBJECT_SIZES,
  OBJECT_LABELS,
  makeObjectJson,
} from "./object-workload";

let input = "";
let value = new GrowingObject();
let dynamic = new JSON.Obj();

function nativeOperation(): void {
  // Same generated serializer entry used by the legacy harness.
  // @ts-ignore: generated by the transform
  value.__SERIALIZE(changetype<usize>(value));
  blackbox(bs.out<string>());
}

function dynamicOperation(): void {
  blackbox(JSON.stringify(dynamic));
}

for (let i = 0; i < OBJECT_SIZES.length; i++) {
  input = makeObjectJson(OBJECT_SIZES[i]);
  const bytes = String.UTF8.byteLength(input);
  const operations = min<i32>(200000, max<i32>(5, (500 * 1024 * 1024) / bytes));
  const label = OBJECT_LABELS[i];
  value = JSON.parse<GrowingObject>(input);
  dynamic = JSON.parse<JSON.Obj>(input);
  expect(JSON.stringify(value)).toBe(input);
  nativeOperation();
  bench("Serialize Object (" + label + ")", nativeOperation, operations, bytes);
  dumpToFile("obj-" + label, "serialize");
  bench(
    "Serialize Object JSON.Obj (" + label + ")",
    dynamicOperation,
    operations,
    bytes,
  );
  dumpToFile("obj-" + label + "-obj", "serialize");
}
